      "director": "Luís Galvão Teles",
      "year": 1975,
      "duration": 73,
      "poster": null,
      "genres": [
        "Documentary"
      ],
      "link": "https://www.batalhacentrodecinema.pt/filmes/01-casegas-1-procissao-dos-bebados",
