      "year": 1995,
      "duration": 8,
      "poster": "https://a.ltrbxd.com/resized/film-poster/9/5/6/6/5/5/956655-hoodoo-mcfiggin-s-christmas-0-500-0-750-crop.jpg?v=216888e3e6",
